List<CoinStats> computeTopCoins(List<Transaction> transactions, bool isAverageProfit) {
  Map<String, CoinStats> statsMap = {};
  for (final transaction in transactions) {
    if (!statsMap.containsKey(transaction.coinName)) {
      statsMap[transaction.coinName] = CoinStats(transaction.coinName, [transaction]);
    } else {
      statsMap[transaction.coinName].transactions.add(transaction);
    }
    statsMap[transaction.coinName].computeStats();
  }

