import org.apache.poi.ss.usermodel.*;
import java.io.FileInputStream;
import java.util.ArrayList;
import java.util.List;

public class ExcelDataReader {
    public static List<Location> readFromExcel(String excelFilePath) throws Exception {
        Workbook workbook = WorkbookFactory.create(new FileInputStream(excelFilePath));
        Sheet sheet = workbook.getSheet("Sheet1");
        int rowCount = sheet.getPhysicalNumberOfRows();
        List<Location> locations = new ArrayList<>();
        for (int rowNum = 1; rowNum <= rowCount; rowNum++) {
            Row row = sheet.getRow(rowNum);
            if (row == null || row.getCell(0) == null) {
                continue;
            }
            String name = row.getCell(0).toString();
            double latitude = row.getCell(1).getNumericCellValue();
            double longitude = row.getCell(2).getNumericCellValue();
            double magneticFieldIntensity = row.getCell(3).getNumericCellValue();
            locations.add(new Location(name, latitude, longitude, magneticFieldIntensity));
        }
        return locations;
    }
}
