Here's a possible implementation in JavaScript:

```js
const carSizes = require('./carSizes.json');

function recommendCarSize(height) {
  let size = Object.keys(carSizes)[0]; // assume first size fits by default

  for (let key in carSizes) {
    const sizeInfo = carSizes[key];
    const heightRange = sizeInfo.heightRange.split('-').map(parseFloat);

    if (height >= heightRange[0] && height <= heightRange[1]) {
      size = key;
      break;
    }
  }

  return size;
}

// example usage
console.log(recommendCarSize(5)); // returns 'midsize'
console.log(recommendCarSize(6.2)); // returns 'suv'
console.log(recommendCarSize(6.9)); // returns 'truck'
```

The `recommendCarSize()` function takes the customer's height as argument, iterates over all the car sizes, checks whether the height falls into the corresponding range, and keeps track of the best match found so far. The function returns the size name once a match is found. If no match is found, it assumes the first size as the default one.

