}
print(correctedContent)

func correctHomophones(in content: String) -> String {
    var result = ""

    for (index, char) in content.enumerated() {
        let substring = content.prefix(upTo: index+1)

        for (homophone, replacement) in homophoneDictionary {
            if let range = substring.range(of: homophone, options: .regularExpression) {
                result += String(substring[..<range.lowerBound]) + replacement + String(substring[range.upperBound..<content.endIndex])
                break
            }
        }

        result += String(char)
    }

    return result
}
```

