#include <iostream>

void bubbleSort(int arr[], int n) {
    bool swapped = true;
    int end = n - 1;

    // Keep swapping adjacent elements if they are in wrong order
    while (swapped) {
        swapped = false;
        for (int i = 0; i <= end - 1; i++) {
            if (arr[i] > arr[i+1]) {
                int temp = arr[i];
                arr[i] = arr[i+1];
                arr[i+1] = temp;
                swapped = true;
            }
        }
        end--;
    }
}

