  return {
    type: notifType,
    messages: formattedNotifs,
    maxWeightedRating: maxWeightedRating,
    weightedAverageRating: maxWeightedRating / Math.max(formattedNotifs.length, 1),
  };
}

function formatMessage(message) {
  // add line breaks and ellipses to long messages
  return message.split('').slice(0, 100).join('') + (message.length > 100 ? '...' : '');
}
