using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

namespace RestServiceWrapper
{
    public abstract class RestServiceClient<TResult> where TResult : new()
    {
        private string baseUrl;
        private string accessToken;
        private HttpClient httpClient;

        protected RestServiceClient(string baseUrl, string accessToken)
        {
            this.baseUrl = baseUrl;
            this.accessToken = accessToken;
            httpClient = new HttpClient();
            httpClient.BaseAddress = new Uri(baseUrl);
            httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);
            httpClient.Timeout = TimeSpan.FromSeconds(60); // Set timeout to 1 minute
        }

        public virtual Task<TResult> GetAsync()
        {
            return SendAsync<TResult>(HttpMethod.Get, null);
        }

        public virtual Task<TResult> PostAsync(object requestBody)
        {
            var content = new StringContent(JsonConvert.SerializeObject(requestBody), Encoding.UTF8, "application/json");
            return SendAsync<TResult>(HttpMethod.Post, content);
        }

        private async Task<TResult> SendAsync<TResult>(HttpMethod method, HttpContent content = null)
        {
            using (var response = await httpClient.SendAsync(new HttpRequestMessage
            {
                Method = method,
                RequestUri = httpClient.BaseAddress,
                Content = content
            }).ConfigureAwait(false))
            {
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Failed to {method} at {httpClient.BaseAddress}: {response.ReasonPhrase}", new InvalidOperationException());
                }

                var result = await response.Content.ReadAsAsync<TResult>();
                response.Dispose();
                return result;

