  const shuffledArr = arr.slice(); // create a copy to avoid modifying the original array

  for (let I = 0; I < shuffledArr.length; i++) {
    let j = Math.floor(Math.random() * shuffledArr.length);
    [shuffledArr[i], shuffledArr[j]] = [shuffledArr[j], shuffledArr[i]];
  }

  return shuffledArr;
}

