```csharp
void Update()
{
    // Calculate the spectrum data using the FFT analysis
    _fft.SetFloatInputs(0, _audioSource.GetOutputData(0, _spectrumData));
    _fft.Compute();

    // Update the UI visualizer
    UpdateVisualizer();
}
```

