Here's an implementation of the requested decorator using NestJS:

```typescript
import { ExecutionContext, Injectable, NestMiddleware } from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class DevelopmentOnlyMiddleware implements NestMiddleware {
  constructor() {}

  resolve(): Function {
    return (...args: any[]) => this.middleware(...args);
  }

  private middleware(context: ExecutionContext, next: CallHandler): Observable<any> {
    const req = context.switchToHttp().getRequest();

    if (req.app.get('env') !== 'development') {
      return next.handle();
    }

    return next.handle().pipe(map(() => false)));
  }
}
```

To use this middleware, you can apply it to your controller or route:

```typescript
import { Controller, Get, UseGuards } from '@nestjs/common';
import { JwtAuthGuard } from './auth/jwt-auth.guard';
import { DevelopmentOnlyGuard } from './development-only.guard';

@Controller()
@UseGuards(JwtAuthGuard)
export class MyController {
  @Get()
  getSomething() {
    return 'This will only be available in development mode!';
  }

  @Get('/admin')
  @UseGuards(DevelopmentOnlyGuard)
  getAdmin() {
    return 'This is for admins only in development mode!';
  }
}
```

In the example above, the `DevelopmentOnlyGuard` will return `false` when running in production mode, so it won't execute the protected routes. However, during development, it will allow access to those routes. This is a simple example, but you can modify the behavior of the guard to fit your specific requirements.

Here's an implementation of the requested decorator using NestJS' `Inject` decorator to access the `process.env.NODE_ENV` value:

```typescript
import { Inject } from '@nestjs/common';
import { ExecutionContext, NestMiddleware } from '@nestjs/core';
import { Observable } from 'rxjs';

@Injectable()
export class EnvironmentGuard implements NestMiddleware {
  constructor(@Inject('REQUEST_HANDLER') private readonly requestHandler: unknown) {}

  public execute(context: ExecutionContext): Observable<any> | Promise<any> | any {
    const req = context.switchToHttp().getRequest();
    const isDevEnv = req.app.get('env') === 'development';

    if (!isDevEnv && this.requestHandler instanceof Function) {
      // If we're in production and the request handler is a function,
      // return false immediately to prevent further execution
      return false;
    }

    return context.execute();
  }
}

// Usage example (as a middleware):
// app.use(new EnvironmentGuard())

// Or as a decorator:
export function IsProduction(): MethodDecorator {
  return CreateMethodDecorator(EnvironmentGuard, () => {
    return true;
  });
}

function CreateMethodDecorator(middleware: typeof EnvironmentGuard, options?: Function): MethodDecorator {
  return Reflect.createMethodDecorator((target: Object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    const methodWithMiddleware = async (...args: any[]) => {
      const ctx = new ExecutionContext();
      ctx.switchToHttp().getRequest();
      await middleware.execute(ctx);
      return await originalMethod.apply(this, args);
    };

    const wrappedMethod = options ? options(methodWithMiddleware) : methodWithMiddleware;

    return Reflect.defineProperty(target, propertyKey, {
      ...descriptor,
      value: wrappedMethod,
    });
  });
}
```

