Here's an implementation of the decorator you requested:

```typescript
import { Injectable } from '@nestjs/common';
import { ExecutionContext, UnauthorizedException } from '@nestjs/core';
import { Observable } from 'rxjs';

@Injectable()
export class DevelopmentModeMiddleware {
  public static use(): any {
    return (target: Function | string, key?: string | symbol) => {
      const originalMethod = Reflect.getOwnMetadata('originalMethod', target, key);
      const originalDescriptor = Reflect.getOwnPropertyDescriptor(target, key);

      Reflect.defineMetadata('originalMethod', originalMethod, target, key);
      Reflect.defineMetadata('originalDescriptor', originalDescriptor, target, key);

      const wrappedMethod = this.wrapMethod(target, key);

      Reflect.setPrototypeOf(wrappedMethod, originalDescriptor.value);
      Object.setPrototypeOf(wrappedMethod, originalDescriptor);
      Reflect.setOwnMetadata('design:type', originalDescriptor.value.constructor, wrappedMethod);
      Reflect.setAccessor(target, key, originalDescriptor.get && originalDescriptor.set);

      return wrappedMethod;
    };
  }

  private wrapMethod(target: Function, methodName: string): any {
    const originalMethod = Reflect.getOwnMetadata('originalMethod', target, methodName);
    const originalDescriptor = Reflect.getOwnPropertyDescriptor(target, methodName);

    const isDevelopmentMode = () => process.env.NODE_ENV === 'development';

    const wrappedMethod = function(...args: any[]) {
      if (!isDevelopmentMode()) {
        throw new UnauthorizedException();
      }

      return originalMethod.apply(this, args);
    };

    wrappedMethod.prototype = originalDescriptor.value.prototype;

    return wrappedMethod;
  }
}
```

