string[] lines = File.ReadAllLines("dataset.txt");
List<double[,]> data = new List<double[,]>();
List<string> labels = new List<string>();
foreach (string line in lines) {
    string[] parts = line.Split('\t');
    double[,] features = new double[1, parts[0].Split(' ').Length];
    int i = 0;
    foreach (string word in parts[0].Split(' ')) {
        features[0, i++] = word.Length;
        foreach (char ch in word) {
            features[0, i++] = ch == '.' ? 1 : 0;
            features[0, i++] = ch == ',' ? 1 : 0;
            features[0, i++] = ch == '!' ? 1 : 0;
            features[0, i++] = ch == '?' ? 1 : 0;
            features[0, i++] = ch == ' ' ? 1 : 0;
        }
    }
    data.Add(features);
    labels.Add(parts[1]);
}

int[] categoryCounts = labels.GroupBy(x => x).Select(g => g.Count()).ToArray();
