3. Create a function to convert the labeled dataset into a feature matrix (i.e., a matrix of word counts) using the `CountVectorizer` class provided by Accord.NET:

   ```csharp
   public static double[,] GetFeatureMatrix(IEnumerable<Sentence> sentences)
   {
       var stopWords = Stopwords.English;

       // Convert each sentence into a dictionary of words and their frequencies
       var dictionary = new Dictionary<string, int>();
       foreach (var sentence in sentences)
       {
           var tokens = sentence.Text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
           foreach (var token in tokens)
           {
               if (!stopWords.Contains(token))
               {
                   int count;
                   if (dictionary.TryGetValue(token, out count))
                   {
                       dictionary[token] = count + 1;
                   }
                   else
                   {
                       dictionary.Add(token, 1);
                   }
               }
           }
       }

       // Convert the dictionary into a sparse feature matrix
       var vectorizer = new CountVectorizer(MinDocumentFrequency: 1)
       {
           Tokenization = CountVectorizer.TokenizationMethod.WordByWord
       };
       var matrix = vectorizer.Transform(sentences).ToArray();

       return matrix;
   }
   ```

