```js
const { promisify } = require('util');
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    // Handle errors from Redis
    this.client.on('error', (err) => {
      console.error(`Redis Client Error: ${err}`);
    });
  }

  /**
   * Check if the Redis connection is alive
   * @returns {boolean} True if connection is alive, false otherwise
   */
  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error(`Redis Connection Error: ${err}`);
      return false;
    }
  }

  /**
   * Get the value of a key in Redis
   * @param {string} key - The key to retrieve
   * @returns {Promise<string>} The value associated with the given key
   */
  async get(key) {
    return promisify(this.client.get)(key);
  }

  /**
   * Set the value of a key in Redis with an expiration time
   * @param {string} key - The key to store
   * @param {*} value - The value to store
   * @param {number} duration - The expiration time in seconds
   * @returns {Promise<number>} The number of keys that were set
   */
  async set(key, value, duration) {
    return promisify(this.client.setex)(key, duration, value);
  }

  /**
   * Delete a key in Redis
   * @param {string} key - The key to delete
   * @returns {Promise<number>} The number of keys that were deleted
   */
  async del(key) {
    return promisify(this.client.del)(key);
  }
}

// Create an instance of RedisClient and export it
const redisClient = new RedisClient();
module.exports = redisClient;
```

