# Define function to check if SID exists in SIDHistory
Function Get-SidInSidHistory($sid) {
    $domainController = "DC=yourdomain,DC=com"
    $filter = "(objectcategory=groupcomputeroruser)"
    $searcher = New-Object -ComObject Microsoft.ActiveDirectory.DirectorySearcher
    $searcher.Filter = "$filter"
    $searcher.PropertiesToLoad.Add("samaccountname")
    $searcher.PropertiesToLoad.Add("sidhistory")
    $searcher.SearchRoot = [ADSI]"LDAP://$domainController"
    $searcher.PageSize = 1000

    Do {
        $results = $searcher.FindAll()
        foreach ($result in $results) {
            $sidHistory = $result.Properties["sidhistory"][0]
            if (-not [string]::IsNullOrEmpty($sidHistory)) {
                $sidHistoryArray = (ConvertFrom-Csv -String $sidHistory).sid
                foreach ($sidHistoryEntry in $sidHistoryArray) {
                    if ($sidHistoryEntry -eq $sid) {
                        return $true
                    }
                }
            }
        }

        # Set up for next page of results
        $searcher.PageIndex++
    } While ($results.Count -gt 0)

    Return $false
}

# Function to recursively search directories and subdirectories
